function accordions(){ $$('.accordion-head').forEach(head=>head.addEventListener('click',()=>{const acc=head.closest('.accordion');acc.classList.toggle('collapsed');head.setAttribute('aria-expanded',!acc.classList.contains('collapsed'))}))}
function chartToggles(){ $$('[data-range]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-range]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const label=$('#range-label'); if(label) label.textContent=btn.dataset.range; randomizeCandles(btn.dataset.range)}));}
function randomizeCandles(seed='1D'){const layer=$('.candle-layer'); if(!layer) return; const chars=[...seed].reduce((a,c)=>a+c.charCodeAt(0),0); layer.innerHTML=''; for(let i=0;i<58;i++){const up=(i+chars)%5!==0; const h=45+((i*17+chars)%205); const bottom=20+((i*23+chars)%120); const el=document.createElement('i'); el.className='candle'; el.style.left=`${i*1.72}%`; el.style.height=`${h}px`; el.style.bottom=`${bottom}px`; el.style.background=up?'#22c55e':'#f7525f'; layer.appendChild(el)}}
