function marketControls(){ $$('[data-chart-option]').forEach(b=>b.addEventListener('click',()=>{const group=b.parentElement; $$('[data-chart-option]',group).forEach(x=>x.classList.remove('active')); b.classList.add('active'); $$('.spark polyline,.spark path').forEach((p,i)=>{p.style.stroke=(b.textContent==='Candles'||(i+Date.now())%2)?'#22c55e':'#2962ff'})}))}
